    for x in range(len(HighScores)-1):
        for y in range(len(HighScores)-x-1):
            a=HighScores[y];b=HighScores[y+1]
            if int(a[1])<int(b[1]) or (int(a[1])==int(b[1]) and int(a[2])<int(b[2])):
                HighScores[y],HighScores[y+1]=b,a
    return HighScores
